contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 baseAmount) public payable {
        require(address(this).balance >= baseAmount);
        require(baseAmount >= 0);

        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("ownerOf(uint256)", tokenId));
        require(ok, "ownerOf failed");
        address owner = abi.decode(ret, (address));

        bool transferReverted;
        bytes memory transferRet;
        try c.transfer(address(this), tokenId) {
            transferReverted = false;
            transferRet = "";
        } catch {
            transferReverted = true;
        }

        if (!transferReverted) {
            (uint256 flashFee, uint256 protocolFee) = c.flashFeeAndProtocolFee();
            require(flashFee + protocolFee <= type(uint256).max - address(c).balance);
            uint256 beforePoolBalance = address(c).balance;
            uint256 beforeThisBalance = address(this).balance;
            bool flashReverted;
            try c.flashLoan(IERC3156FlashBorrower(address(this)), address(c), tokenId, "") {
                flashReverted = false;
            } catch {
                flashReverted = true;
            }
            if (!flashReverted) {
                assert(address(this).balance + flashFee + protocolFee >= beforeThisBalance);
                assert(address(c).balance >= beforePoolBalance);
            } else {
                assert(address(c).balance == beforePoolBalance);
                assert(address(this).balance == beforeThisBalance);
            }
        } else {
            assert(owner != address(this));
        }
    }

    receive() external payable {}

    function onFlashLoan(
        address,
        address,
        uint256,
        uint256,
        bytes calldata
    ) external returns (bytes32) {
        return keccak256("onFlashLoan");
    }
}

