contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        uint256 tokenId,
        uint256 tokenWeight,
        uint256 payAmount
    ) public payable {
        require(feeRate <= 5000);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;
        uint256[] memory tokenWeights = new uint256[](1);
        tokenWeights[0] = tokenWeight;

        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        if (baseToken == address(0)) {
            require(address(this).balance >= payAmount);
            try c.buy{value: payAmount}(tokenIds, tokenWeights, proof) returns (uint256 a, uint256 b, uint256 d) {
                netInputAmount = a;
                feeAmount = b;
                protocolFeeAmount = d;
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.buy{value: 0}(tokenIds, tokenWeights, proof) returns (uint256 a, uint256 b, uint256 d) {
                netInputAmount = a;
                feeAmount = b;
                protocolFeeAmount = d;
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        if (!reverted) {
            assert(
                afterVirtualNft == beforeVirtualNft - tokenWeight &&
                afterVirtualBase >= beforeVirtualBase &&
                netInputAmount == feeAmount + protocolFeeAmount ||
                (beforeVirtualNft < tokenWeight && afterVirtualNft == 0)
            );
        } else {
            assert(afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft);
        }
    }
}

